// LISTA DE PRODUTOS CADASTRADOS

let produtos = [

    { codigo: 1, descricao: "Cadeira gamer", quantidade: 12, valor: 699 },
        { codigo: 2, descricao: "Mouse Logitech", quantidade: 38, valor: 99 },
            { codigo: 3, descricao: "Teclado gamer", quantidade: 15, valor: 150 },
                { codigo: 4, descricao: "Monitor Samsung", quantidade: 8, valor: 899 },
                    { codigo: 5, descricao: "Notebook Dell", quantidade: 5, valor: 3500 },
                        { codigo: 6, descricao: "Fone Bluetooth", quantidade: 25, valor: 120 },
                            { codigo: 7, descricao: "Carregador USB", quantidade: 40, valor: 35 },
                                { codigo: 8, descricao: "Mesa de escritorio", quantidade: 10, valor: 450 },
                                    { codigo: 9, descricao: "Impressora Epson", quantidade: 4, valor: 750 },
                                        { codigo: 10, descricao: "Webcam Logitech", quantidade: 18, valor: 210 }

                                        ];

                                        let proximoCodigo = 11;


                                        // CADASTRAR PRODUTO

                                        function cadastrarProduto() {

                                            let descricao = document.getElementById("descricao").value.trim();
                                                let quantidade = Number(document.getElementById("quantidade").value);
                                                    let valor = Number(document.getElementById("valor").value);

                                                        if (descricao.length < 5) {
                                                                alert("A descrição precisa ter pelo menos 5 caracteres!");
                                                                        return;
                                                                            }

                                                                                if (!Number.isInteger(quantidade) || quantidade < 1) {
                                                                                        alert("Quantidade inválida!");
                                                                                                return;
                                                                                                    }

                                                                                                        if (!Number.isFinite(valor) || valor < 0) {
                                                                                                                alert("Valor inválido!");
                                                                                                                        return;
                                                                                                                            }

                                                                                                                                let novoProduto = {
                                                                                                                                        codigo: proximoCodigo++,
                                                                                                                                                descricao: descricao,
                                                                                                                                                        quantidade: quantidade,
                                                                                                                                                                valor: valor
                                                                                                                                                                    };

                                                                                                                                                                        produtos.push(novoProduto);

                                                                                                                                                                            document.getElementById("descricao").value = "";
                                                                                                                                                                                document.getElementById("quantidade").value = "";
                                                                                                                                                                                    document.getElementById("valor").value = "";

                                                                                                                                                                                        listarProdutos();

                                                                                                                                                                                            alert("Produto cadastrado com sucesso!");
                                                                                                                                                                                            }


                                                                                                                                                                                            // LISTAR PRODUTOS

                                                                                                                                                                                            function listarProdutos() {

                                                                                                                                                                                                let lista = document.getElementById("listaProdutos");

                                                                                                                                                                                                    let busca = document.getElementById("busca").value.toLowerCase();

                                                                                                                                                                                                        lista.innerHTML = "";

                                                                                                                                                                                                            let filtrados = produtos.filter(produto =>
                                                                                                                                                                                                                    produto.descricao.toLowerCase().includes(busca) ||
                                                                                                                                                                                                                            String(produto.codigo).includes(busca)
                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                    filtrados.forEach(produto => {

                                                                                                                                                                                                                                            let status = produto.quantidade <= 5
                                                                                                                                                                                                                                                        ? '<span class="status-baixo">Estoque baixo</span>'
                                                                                                                                                                                                                                                                    : '<span class="status-ok">Disponível</span>';

                                                                                                                                                                                                                                                                            lista.innerHTML += `
                                                                                                                                                                                                                                                                                        <tr>

                                                                                                                                                                                                                                                                                                        <td>${produto.codigo}</td>

                                                                                                                                                                                                                                                                                                                        <td>${produto.descricao}</td>

                                                                                                                                                                                                                                                                                                                                        <td>${produto.quantidade}</td>

                                                                                                                                                                                                                                                                                                                                                        <td>R$ ${produto.valor.toFixed(2)}</td>

                                                                                                                                                                                                                                                                                                                                                                        <td>R$ ${(produto.quantidade * produto.valor).toFixed(2)}</td>

                                                                                                                                                                                                                                                                                                                                                                                        <td>${status}</td>

                                                                                                                                                                                                                                                                                                                                                                                                        <td>

                                                                                                                                                                                                                                                                                                                                                                                                                            <button class="editar"
                                                                                                                                                                                                                                                                                                                                                                                                                                                onclick="atualizarValor(${produto.codigo})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Editar valor
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button class="entrada"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onclick="adicionarQuantidade(${produto.codigo})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Entrada
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button class="saida"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onclick="retirarQuantidade(${produto.codigo})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Saída
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button class="excluir"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onclick="excluirProduto(${produto.codigo})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Excluir
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    atualizarResumo();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ATUALIZAR VALOR

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function atualizarValor(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let produto = produtos.find(p => p.codigo === codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alert("Produto não encontrado!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let novoValor = Number(prompt("Digite o novo valor:"));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!Number.isFinite(novoValor) || novoValor < 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Valor inválido!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                produto.valor = novoValor;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alert("Valor atualizado!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ADICIONAR QUANTIDADE

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function adicionarQuantidade(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let produto = produtos.find(p => p.codigo === codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alert("Produto não encontrado!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let quantidade = Number(prompt("Quantidade que deseja adicionar:"));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!Number.isInteger(quantidade) || quantidade < 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alert("Quantidade inválida!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    produto.quantidade += quantidade;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert("Entrada realizada com sucesso!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // RETIRAR QUANTIDADE

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function retirarQuantidade(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let produto = produtos.find(p => p.codigo === codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert("Produto não encontrado!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let quantidade = Number(prompt("Quantidade que deseja retirar:"));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!Number.isInteger(quantidade) || quantidade < 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alert("Quantidade inválida!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (quantidade > produto.quantidade) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Estoque insuficiente!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                produto.quantidade -= quantidade;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alert("Saída realizada com sucesso!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // EXCLUIR PRODUTO

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function excluirProduto(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let confirmar = confirm("Deseja excluir este produto?");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!confirmar) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    produtos = produtos.filter(p => p.codigo !== codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert("Produto excluído!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ATUALIZAR RESUMO

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function atualizarResumo() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let totalProdutos = produtos.length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let totalQuantidade = produtos.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            (total, produto) => total + produto.quantidade, 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let valorEstoque = produtos.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            (total, produto) => total + (produto.quantidade * produto.valor), 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let estoqueBaixo = produtos.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            produto => produto.quantidade <= 5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ).length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("totalProdutos").innerText = totalProdutos;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("totalQuantidade").innerText = totalQuantidade;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("valorEstoque").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "R$ " + valorEstoque.toFixed(2);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("estoqueBaixo").innerText = estoqueBaixo;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // INICIAR SISTEMA

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarProdutos();